<template><section class="screen settings-screen"><header class="page-header"><div><p class="eyebrow">WORKSPACE / SETTINGS</p><h1>Settings</h1><p class="subtitle">Tune PQT Forge to the way you work.</p></div><span class="settings-version">PQT FORGE / {{ settingsController.version }}</span></header><div class="settings-layout"><nav class="settings-nav"><button v-for="section in sections" :key="section.id" :class="{active:activeSection===section.id}" @click="activeSection=section.id">{{section.glyph}} {{section.label}}</button></nav><article class="panel settings-panel"><template v-if="activeSection==='general'"><p class="eyebrow">GENERAL</p><h2>Application behavior</h2><div class="settings-row"><span><b>Launch services on startup</b><small>Start your default group when PQT Forge opens.</small></span><button class="toggle" :class="{on:settingsController.autoStart}" @click="settingsController.autoStart=!settingsController.autoStart"><i/></button></div></template><template v-else-if="activeSection==='environment'"><p class="eyebrow">ENVIRONMENT</p><h2>System PATH</h2><div class="path-toolbar"><button class="action-button" @click="path.load()">Refresh</button><input v-model="newPath" placeholder="Add absolute folder path" @keyup.enter="addPath"/><button class="action-button" @click="addPath">Add</button></div><div class="path-list"><div v-for="(entry,index) in path.state.list" :key="entry.path+index" class="path-row"><code>{{entry.path}}</code><button class="icon-button" @click="path.remove(index)">×</button></div></div><button class="settings-save" @click="path.save()">Save PATH</button></template><template v-else-if="activeSection==='hosts'"><p class="eyebrow">HOSTS</p><h2>System hosts file</h2><p class="muted">Digest guarded editing for local hostname resolution.</p><div class="path-toolbar"><button class="action-button" @click="hosts.load()">Refresh</button></div><textarea v-model="hosts.state.content" class="hosts-editor" spellcheck="false"></textarea><button class="settings-save" @click="hosts.save()">Save hosts</button></template><template v-else-if="activeSection==='appearance'"><p class="eyebrow">APPEARANCE</p><h2>Visual system</h2><label class="setting-select"><span>Theme</span><select v-model="settingsController.theme"><option>Dark graphite</option><option>Dark high contrast</option></select></label></template><template v-else><p class="eyebrow">ABOUT</p><h2>PQT Forge</h2><p class="about-copy">Developer Environment Manager</p></template><button v-if="!['environment','hosts'].includes(activeSection)" class="settings-save" @click="persist">Save changes</button></article></div></section></template>
<script setup lang="ts">
import {ref} from 'vue';import {loadSettings,saveSettings,settingsController} from '../state/settingsController';import {showNotice} from '../state/app';import {pathController} from '../state/pathController';import {hostsController} from '../state/hostsController';const activeSection=ref('general'),newPath=ref('');const path=pathController,hosts=hostsController;const addPath=()=>{path.add(newPath.value);newPath.value=''};const persist=async()=>{await saveSettings();showNotice('Settings saved locally')};loadSettings().catch(()=>undefined);path.load().catch(()=>undefined);hosts.load().catch(()=>undefined);const sections=[{id:'general',label:'General',glyph:'⚙'},{id:'environment',label:'Environment',glyph:'⌁'},{id:'hosts',label:'Hosts',glyph:'↔'},{id:'appearance',label:'Appearance',glyph:'◐'},{id:'about',label:'About PQT Forge',glyph:'i'}];
</script>
